DATA = json.loads(zlib.decompress(base64.b85decode(PACKED)))

def digest(data):
    return hashlib.sha256(data).hexdigest()

def canon(path):
    return path.read_bytes().replace(b'\r\n', b'\n')

def fail(message):
    raise SystemExit('N1 recipe refused: ' + message)

def main():
    if len(sys.argv) != 2:
        fail('usage: perf_lab_n1.py PATH_TO_NATIVE_PERF_LAB')
    lab = Path(sys.argv[1]).resolve(strict=True)
    raw = canon(lab)
    found = digest(raw)
    matches = [(name, item) for name, item in DATA['sources'].items()
               if found in (item['input_sha256'], item['post_sha256'])]
    if len(matches) != 1:
        fail('unknown perf_lab source SHA256 ' + found)
    name, source = matches[0]
    legacy = name == 'main'
    folder = lab.parent / 'perf_lab' if legacy else lab.parent
    crate = lab.parents[1] if legacy else lab.parents[2]
    pipeline = canon(crate / 'src/mutation/pipeline.rs').decode()
    bulk = canon(crate / 'src/bulk_load.rs').decode()
    signature = re.search(r'pub fn new\s*\(\s*store:\s*Arc<StoreService>,\s*([^)]*)\)', pipeline)
    if signature is None:
        fail('missing native MutationPipeline constructor')
    parameter = re.sub(r'\s+', '', signature.group(1)).rstrip(',')
    if parameter != source['constructor']:
        fail('unknown native MutationPipeline constructor: ' + parameter)
    if source['bulk_field'] not in bulk:
        fail('unknown native BulkLoadRequest malformed-input field')
    checks = {}
    if not legacy:
        modes = canon(folder / 'modes.rs')
        if digest(modes) != source['modes_sha256']:
            fail('unknown native modes.rs; no workload substitution')
        checks['modes.rs'] = digest(modes)
    if name == 'native':
        existing = canon(folder / 'durable.rs')
        allowed = (DATA['durable_input_sha256'], digest(DATA['files']['durable.rs'].encode()))
        if digest(existing) not in allowed:
            fail('unknown durable.rs; no workload substitution')
        checks['durable_input_or_post'] = digest(existing)
    outputs = {folder / p: DATA['files'][p].encode() for p in source['files']}
    outputs[lab] = source['post'].encode()
    # Check the whole operation before writing anything.
    for path, expected in outputs.items():
        if path.exists() and path != lab:
            actual = canon(path)
            if actual != expected and not (name == 'native' and path.name == 'durable.rs'
                    and digest(actual) == DATA['durable_input_sha256']):
                fail('unexpected existing payload ' + str(path))
    present = found == source['post_sha256']
    if present and any(not p.exists() or canon(p) != b for p, b in outputs.items()):
        fail('partial/modified postimage; do not repair silently')
    folder.mkdir(exist_ok=True)
    for path, expected in outputs.items():
        if not present:
            path.write_bytes(expected)
    head = subprocess.check_output(['git', '-C', str(crate), 'rev-parse', 'HEAD'],
                                   text=True).strip()
    receipt = {'profile': DATA['profile'], 'source_revision': head, 'source_kind': name,
               'input_sha256': source['input_sha256'], 'post_sha256': source['post_sha256'],
               'script_sha256': digest(Path(__file__).read_bytes()), 'native_checks': checks,
               'outputs': {str(p.relative_to(crate)): digest(b) for p, b in outputs.items()}}
    (folder / 'n1-measurement-receipt.json').write_text(
        json.dumps(receipt, indent=2) + '\n', encoding='utf-8')
    print('present' if present else 'applied')
    return 0

if __name__ == '__main__':
    raise SystemExit(main())
